+			.filter((goal) => goal.steps.length === 0)
+			.map((goal) => goal.id),
+		cardsWithoutReviewEvidence: input.decks.flatMap((deck) =>
+			deck.cards.filter((card) => !reviewedCardIds.has(card.id)).map((card) => card.id)
+		),
+	};
