					if (!nextState.topicsExplored.includes(entry.topic)) nextState.topicsExplored.push(entry.topic);
				}
				nextState.lastSessionAt = Date.now();
			});
			await this.refreshDerivedLearnerProfile();
		}

		return count;
	}

