			},
			baselineScore: attempt.baselineScore,
			afterScore: attempt.afterScore,
			scoreDelta: attempt.scoreDelta,
			accepted: attempt.accepted,
			completedAt: new Date().toISOString(),
		});
		if (attempt.accepted) {
