	const reviewedCardIds = new Set(input.cardReviews.map((review) => review.cardId));
	return {
		missingProfileBeliefCategories: PROFILE_BELIEF_CATEGORIES.filter((category) => !beliefCategories.has(category)),
		topicsWithoutPerformanceEvidence: input.learnerState.topicsExplored.filter((topic) => !profileTopics.has(topic)),
		topicsWithoutRetentionEvidence: input.learnerState.topicProfiles
			.filter((profile) => profile.retention === null)
